  select * into t from pg_trigger where tgrelid=to_regclass(expected->>'relation') and tgname=expected->>'name' and not tgisinternal;
  if t.oid is null or t.tgenabled::text is distinct from expected->>'enabled'
   or encode(sha256(convert_to(pg_get_triggerdef(t.oid),'UTF8')),'hex') is distinct from expected->>'definition_sha256'
  then raise exception 'automatic_forward_trigger_changed: %.%',expected->>'relation',expected->>'name'; end if;
 end loop;
 foreach relation_name in array array['private.creator_eligibility_declarations','private.creator_provider_observation_control','private.creator_provider_observation_jobs'] loop
  if not exists(select 1 from pg_class where oid=to_regclass(relation_name) and relrowsecurity and relforcerowsecurity)
  then raise exception 'automatic_forward_private_table_guard_changed: %',relation_name; end if;
  foreach role_name in array array['anon','authenticated','service_role'] loop
   if has_table_privilege(role_name,relation_name,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
   then raise exception 'automatic_forward_raw_api_grant: %',relation_name; end if;
  end loop;
 end loop;

 foreach signature in array array['public.prepare_native_production_paid_video(uuid, text, text, text, integer)','public.create_native_production_paid_video_intent(uuid, text)','public.claim_native_production_paid_video_checkout(uuid, uuid, text)','public.begin_creator_money_checkout(uuid, uuid)','public.record_native_production_checkout_preflight(uuid, uuid, uuid, text, text, bigint, text)','public.accept_native_production_paid_video_receipt(uuid, text, text)','public.resolve_native_production_witness_context(uuid, uuid, uuid, boolean)','public.accept_native_production_witness_enrollment(uuid, uuid, uuid, text, text, text)','public.accept_native_production_verified_witness(uuid, uuid, uuid, text, text, text, bigint, bigint, uuid, bigint)','public.accept_native_production_launch_ready(uuid, uuid, uuid, text, uuid, text, bigint, bigint)','public.accept_native_production_verified_store_facts(uuid, text, text)','public.reconcile_native_production_paid_video_access(uuid)','public.reconcile_native_production_dispatch(uuid, uuid, uuid)','public.process_revenuecat_app_store_event_atomic(text, text, uuid, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text, timestamp with time zone)','public.process_revenuecat_google_play_event_atomic(text, text, uuid, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text, timestamp with time zone)','public.process_revenuecat_terminal_event_atomic(text, text, text, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, text, text, text, text)'] loop
  definition:=pg_get_functiondef(signature::regprocedure);
  if position(marker in definition)=0 then raise exception 'automatic_forward_root_anchor_missing: %',signature; end if;
  if position(marker||gate in definition)=0 then
   execute overlay(definition placing marker||gate from position(marker in definition) for length(marker));
  end if;
 end loop;
